1. using System;
2. using System.Collections.Concurrent;
3. using ContosoUniversity.Models;
4. 
5. namespace ContosoUniversity.Services
6. {
7.     public class NotificationService : IDisposable
8.     {
9.         // Static shared queue across application instances (simple in-memory alternative to MSMQ)
10.        private static readonly ConcurrentQueue<Notification> _queue = new();
11.        private static readonly int _maxQueueLength = 500; // basic cap to prevent unbounded growth
12. 
13.        public NotificationService()
14.        {
15.            // No initialization required for in-memory queue
16.        }
17. 
18.        public void SendNotification(string entityType, string entityId, EntityOperation operation, string userName = null)
18.        {
19.            SendNotification(entityType, entityId, null, operation, userName);
20.        }
21. 
22.        public void SendNotification(string entityType, string entityId, string entityDisplayName, EntityOperation operation, string userName = null)
22.        {
23.            try
23.            {
24.                var notification = new Notification
24.                {
25.                    EntityType = entityType,
26.                    EntityId = entityId,
27.                    Operation = operation.ToString(),
28.                    Message = GenerateMessage(entityType, entityId, entityDisplayName, operation),
29.                    CreatedAt = DateTime.Now,
30.                    CreatedBy = userName ?? "System",
31.                    IsRead = false
32.                };
33. 
34.                _queue.Enqueue(notification);
34. 
35.                // Enforce max queue length (best-effort)
35.                while (_queue.Count > _maxQueueLength && _queue.TryDequeue(out _)) { }
36.            }
37.            catch (Exception ex)
37.            {
38.                System.Diagnostics.Debug.WriteLine($"Failed to enqueue notification: {ex.Message}");
39.            }
40.        }
41. 
42.        public Notification ReceiveNotification()
42.        {
43.            try
43.            {
44.                return _queue.TryDequeue(out var notification) ? notification : null;
45.            }
45.            catch (Exception ex)
46.            {
46.                System.Diagnostics.Debug.WriteLine($"Failed to receive notification: {ex.Message}");
47.                return null;
48.            }
49.        }
50. 
51.        public void MarkAsRead(int notificationId)
51.        {
52.            // No-op for in-memory implementation (persistence not implemented)
53.        }
54. 
55.        private string GenerateMessage(string entityType, string entityId, string entityDisplayName, EntityOperation operation)
55.        {
56.            var displayText = !string.IsNullOrWhiteSpace(entityDisplayName)
56.                ? $"{entityType} '{entityDisplayName}'"
57.                : $"{entityType} (ID: {entityId})";
58. 
59.            return operation switch
59.            {
60.                EntityOperation.CREATE => $"New {displayText} has been created",
61.                EntityOperation.UPDATE => $"{displayText} has been updated",
62.                EntityOperation.DELETE => $"{displayText} has been deleted",
63.                _ => $"{displayText} operation: {operation}"
64.            };
65.        }
66. 
67.        public void Dispose()
67.        {
68.            // Nothing to dispose for in-memory queue
69.        }
70.    }
71. }
