23.        protected override void OnModelCreating(ModelBuilder modelBuilder)
23.        {
24.            // Configure all DateTime properties to use datetime2
25.            foreach (var entityType in modelBuilder.Model.GetEntityTypes())
25.            {
26.                var properties = entityType.ClrType.GetProperties()
26.                    .Where(p => p.PropertyType == typeof(DateTime) || p.PropertyType == typeof(DateTime?));
27. 
28.                foreach (var property in properties)
28.                {
29.                    modelBuilder.Entity(entityType.ClrType)
29.                        .Property(property.Name)
30.                        .HasColumnType("datetime2");
31.                }
32.            }
33. 
34.            modelBuilder.Entity<Course>().ToTable("Course");
34.            modelBuilder.Entity<Enrollment>().ToTable("Enrollment");
35.            modelBuilder.Entity<Department>().ToTable("Department");
36.            modelBuilder.Entity<OfficeAssignment>().ToTable("OfficeAssignment");
37.            modelBuilder.Entity<CourseAssignment>().ToTable("CourseAssignment");
38.            modelBuilder.Entity<Notification>().ToTable("Notification");
39. 
40.            // Configure Table-per-Hierarchy (TPH) inheritance for Person
41.            // Map the base Person class and its derived classes to a single table
42.            modelBuilder.Entity<Person>()
42.                .ToTable("Person")
43.                .HasDiscriminator<string>("Discriminator")
43.                .HasValue<Student>("Student")
44.                .HasValue<Instructor>("Instructor");
45. 
46.            // Configure composite key for CourseAssignment
47.            modelBuilder.Entity<CourseAssignment>()
47.                .HasKey(c => new { c.CourseID, c.InstructorID });
48. 
49.            // Configure relationships
50.            modelBuilder.Entity<CourseAssignment>()
50.                .HasOne(m => m.Course)
51.                .WithMany(t => t.CourseAssignments)
52.                .HasForeignKey(m => m.CourseID);
53. 
