using ContosoUniversity.Models;
using ContosoUniversity.Services;
using System;
using System.Collections.Generic;
using Xunit;

namespace ContosoUniversity.Tests.Services
{
    public class NotificationServiceTests : IDisposable
    {
        private readonly NotificationService _sut;

        public NotificationServiceTests()
        {
            _sut = new NotificationService();
            // Drain the static queue to isolate tests
            while (_sut.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain queue after each test
            while (_sut.ReceiveNotification() != null) { }
            _sut.Dispose();
        }

        [Fact]
        public void SendNotification_WithDisplayName_CreatesNotificationWithNameInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "admin");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification.EntityType);
            Assert.Equal("1", notification.EntityId);
            Assert.Equal("CREATE", notification.Operation);
            Assert.Contains("John Doe", notification.Message);
            Assert.Contains("Student", notification.Message);
            Assert.Contains("created", notification.Message);
            Assert.Equal("admin", notification.CreatedBy);
            Assert.False(notification.IsRead);
        }

        [Fact]
        public void SendNotification_WithoutDisplayName_CreatesNotificationWithIdInMessage()
        {
            // Arrange & Act
            _sut.SendNotification("Course", "42", EntityOperation.UPDATE);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Contains("ID: 42", notification.Message);
            Assert.Contains("updated", notification.Message);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void SendNotification_WithNullUserName_DefaultsToSystem()
        {
            // Arrange & Act
            _sut.SendNotification("Student", "1", EntityOperation.CREATE, null);

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification.CreatedBy);
        }

        [Fact]
        public void ReceiveNotification_QueueHasItems_ReturnsNotification()
        {
            // Arrange
            _sut.SendNotification("Student", "1", "Alice", EntityOperation.CREATE, "user1");

            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.NotNull(result);
            Assert.Equal("Student", result.EntityType);
            Assert.Equal("1", result.EntityId);
        }

        [Fact]
        public void ReceiveNotification_QueueIsEmpty_ReturnsNull()
        {
            // Act
            var result = _sut.ReceiveNotification();

            // Assert
            Assert.Null(result);
        }

        [Fact]
        public void ReceiveNotification_MultipleSends_ReturnsInFifoOrder()
        {
            // Arrange
            _sut.SendNotification("A", "1", EntityOperation.CREATE);
            _sut.SendNotification("B", "2", EntityOperation.UPDATE);

            // Act & Assert
            var first = _sut.ReceiveNotification();
            Assert.NotNull(first);
            Assert.Equal("A", first.EntityType);

            var second = _sut.ReceiveNotification();
            Assert.NotNull(second);
            Assert.Equal("B", second.EntityType);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendNotification_DifferentOperations_GeneratesCorrectMessage(EntityOperation operation, string expectedVerb)
        {
            // Act
            _sut.SendNotification("Entity", "1", "TestEntity", operation, "user");

            // Assert
            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains(expectedVerb, notification.Message);
            Assert.Equal(operation.ToString(), notification.Operation);
        }

        [Fact]
        public void SendNotification_DefaultOperation_GeneratesMessageWithOperationName()
        {
            // The default case in the switch uses the operation enum value
            var unknownOp = (EntityOperation)999;
            _sut.SendNotification("Entity", "1", "Test", unknownOp, "user");

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("operation:", notification.Message);
        }

        [Fact]
        public void SendNotification_QueueCapEnforcement_TrimsOldestWhenOverMax()
        {
            // Send more than 500 items to trigger the cap enforcement
            for (int i = 0; i < 510; i++)
            {
                _sut.SendNotification("Type", i.ToString(), EntityOperation.CREATE, "user");
            }

            // Queue should be at or below 500 after enforcement
            int count = 0;
            while (_sut.ReceiveNotification() != null)
            {
                count++;
            }
            Assert.True(count <= 500, $"Expected queue size <= 500 after cap enforcement, got {count}");
        }

        [Fact]
        public void SendNotification_CreatedAtIsSet()
        {
            var before = DateTime.Now.AddSeconds(-1);

            _sut.SendNotification("Student", "1", EntityOperation.CREATE);

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.True(notification.CreatedAt >= before);
            Assert.True(notification.CreatedAt <= DateTime.Now.AddSeconds(1));
        }

        [Fact]
        public void MarkAsRead_DoesNotThrow()
        {
            var exception = Record.Exception(() => _sut.MarkAsRead(1));
            Assert.Null(exception);
        }

        [Fact]
        public void MarkAsRead_WithAnyId_DoesNotThrow()
        {
            var exception = Record.Exception(() => _sut.MarkAsRead(int.MaxValue));
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_DoesNotThrow()
        {
            var service = new NotificationService();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void Dispose_CalledMultipleTimes_DoesNotThrow()
        {
            var service = new NotificationService();
            service.Dispose();
            var exception = Record.Exception(() => service.Dispose());
            Assert.Null(exception);
        }

        [Fact]
        public void SendNotification_WithEmptyDisplayName_UsesIdFormat()
        {
            _sut.SendNotification("Student", "5", "", EntityOperation.CREATE, "user");

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 5", notification.Message);
        }

        [Fact]
        public void SendNotification_WithWhitespaceDisplayName_UsesIdFormat()
        {
            _sut.SendNotification("Student", "5", "   ", EntityOperation.CREATE, "user");

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains("ID: 5", notification.Message);
        }

        [Fact]
        public void SendNotification_CreateOperation_MessageStartsWithNew()
        {
            _sut.SendNotification("Student", "1", "Alice", EntityOperation.CREATE, "user");

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.StartsWith("New", notification.Message);
        }

        [Fact]
        public void SendNotification_DeleteOperation_MessageContainsDeleted()
        {
            _sut.SendNotification("Course", "100", "Physics", EntityOperation.DELETE, "user");

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course 'Physics' has been deleted", notification.Message);
        }

        [Fact]
        public void SendNotification_UpdateWithoutDisplayName_MessageContainsUpdated()
        {
            _sut.SendNotification("Department", "7", EntityOperation.UPDATE);

            var notification = _sut.ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Department (ID: 7) has been updated", notification.Message);
        }
    }
}

