        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempDir;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.CreateWithSeedData();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempDir);
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempDir))
            {
                try { Directory.Delete(_tempDir, true); } catch { }
            }
        }

        #region Index Tests

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var courses = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.Equal(2, courses.Count);
        }

        [Fact]
        public void Index_CoursesIncludeDepartment()
        {
            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var courses = Assert.IsAssignableFrom<List<Course>>(result.Model);
            Assert.All(courses, c => Assert.NotNull(c.Department));
        }

        #endregion

        #region Details Tests

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var result = _controller.Details(1001) as ViewResult;

            Assert.NotNull(result);
            var course = Assert.IsType<Course>(result.Model);
            Assert.Equal("Intro to CS", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.NotNull(course.Department);
        }

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        #endregion

        #region Create Tests

        [Fact]
        public void Create_GET_ReturnsViewWithSelectList()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.IsType<Course>(result.Model);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
            Assert.IsType<SelectList>(_controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Create_POST_ValidCourse_NoFile_RedirectsToIndex()
        {
            var course = new Course
            {
                CourseID = 2001,
                Title = "New Course",
                Credits = 3,
                DepartmentID = 1
            };

            var result = _controller.Create(course, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Create_POST_ValidCourse_SavesToDB()
        {
            var course = new Course
            {
                CourseID = 2002,
                Title = "Saved Course",
                Credits = 4,
                DepartmentID = 1
            };

            _controller.Create(course, null!);

            var saved = _context.Courses.Find(2002);
            Assert.NotNull(saved);
            Assert.Equal("Saved Course", saved.Title);
            Assert.Equal(4, saved.Credits);
            Assert.Equal(1, saved.DepartmentID);
        }

        [Fact]
        public void Create_POST_InvalidModelState_ReturnsViewWithSelectList()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 3001, DepartmentID = 1 };

            var result = _controller.Create(course, null!) as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Create_POST_InvalidFileExtension_AddsModelError()
        {
            var course = new Course { CourseID = 4001, Title = "Test", Credits = 3, DepartmentID = 1 };
            var mockFile = CreateMockFile("test.exe", 1000);

            var result = _controller.Create(course, mockFile) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.Contains(errors, e => e.ErrorMessage.Contains("valid image file"));
        }

        [Fact]
        public void Create_POST_OversizedFile_AddsModelError()
        {
            var course = new Course { CourseID = 4002, Title = "Test", Credits = 3, DepartmentID = 1 };
            var mockFile = CreateMockFile("test.jpg", 6 * 1024 * 1024); // 6MB

            var result = _controller.Create(course, mockFile) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
            Assert.Contains(errors, e => e.ErrorMessage.Contains("5MB"));
        }

        [Fact]
        public void Create_POST_ValidImageFile_SavesFileAndRedirects()
        {
            var course = new Course { CourseID = 4003, Title = "With Image", Credits = 3, DepartmentID = 1 };
            var mockFile = CreateMockFile("photo.png", 1024);

            var result = _controller.Create(course, mockFile);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);

            var saved = _context.Courses.Find(4003);
            Assert.NotNull(saved);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void Create_POST_AllowedExtensions_DoNotAddModelError(string ext)
        {
            var course = new Course { CourseID = 5000 + ext.GetHashCode(), Title = "Test", Credits = 3, DepartmentID = 1 };
            var mockFile = CreateMockFile($"test{ext}", 1024);

            var result = _controller.Create(course, mockFile);

            Assert.IsType<RedirectToActionResult>(result);
            Assert.False(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        #endregion

        #region Edit Tests

        [Fact]
        public void Edit_GET_ValidId_ReturnsViewWithCourse()
        {
            var result = _controller.Edit(1001) as ViewResult;

            Assert.NotNull(result);
            var course = Assert.IsType<Course>(result.Model);
            Assert.Equal("Intro to CS", course.Title);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
        }

        [Fact]
        public void Edit_GET_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_GET_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_POST_ValidCourse_NoFile_RedirectsToIndex()
        {
            var course = _context.Courses.Find(1001)!;
            course.Title = "Updated CS";
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var result = _controller.Edit(course, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_POST_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 1001, DepartmentID = 1 };

            var result = _controller.Edit(course, null!) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Edit_POST_InvalidFileExtension_AddsModelError()
        {
