            var course = _context.Courses.Find(1002)!;
            course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test.jpg";
            _context.SaveChanges();

            // Should not throw even though file doesn't exist
            var result = _controller.DeleteConfirmed(1002);
            Assert.IsType<RedirectToActionResult>(result);
        }

        #endregion

        #region Helpers

        private static IFormFile CreateMockFile(string fileName, long fileSize)
        {
            var content = new byte[Math.Min(fileSize, 1024)];
            var stream = new MemoryStream(content);
            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns(fileName);
            mockFile.Setup(f => f.Length).Returns(fileSize);
            mockFile.Setup(f => f.OpenReadStream()).Returns(stream);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>())).Callback<Stream>(s =>
            {
                stream.Position = 0;
                stream.CopyTo(s);
            });
            return mockFile.Object;
        }

        #endregion
    }
}

