namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;
        private readonly NotificationService _notificationService;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            _notificationService = new NotificationService();
            // Drain the static queue
            while (_notificationService.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain queue
            while (_notificationService.ReceiveNotification() != null) { }
            _notificationService.Dispose();
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_EmptyQueue_ReturnsSuccessWithEmptyList()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var value = result.Value;
            Assert.NotNull(value);
            // Use reflection to check the anonymous type properties
            var successProp = value.GetType().GetProperty("success");
            Assert.NotNull(successProp);
            Assert.True((bool)successProp.GetValue(value)!);

            var countProp = value.GetType().GetProperty("count");
            Assert.NotNull(countProp);
            Assert.Equal(0, (int)countProp.GetValue(value)!);
        }

        [Fact]
        public void GetNotifications_WithItems_ReturnsNotifications()
        {
            // Put some items in the queue via the service
            _notificationService.SendNotification("Student", "1", "Alice", EntityOperation.CREATE, "user");
            _notificationService.SendNotification("Course", "2", "Physics", EntityOperation.UPDATE, "user");

            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var value = result.Value;
            Assert.NotNull(value);

            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);

            var countProp = value.GetType().GetProperty("count");
            var count = (int)countProp!.GetValue(value)!;
            Assert.True(count >= 1);
        }

        [Fact]
        public void GetNotifications_LimitsTo10()
        {
            // Add 15 items to queue
            for (int i = 0; i < 15; i++)
            {
                _notificationService.SendNotification("Entity", i.ToString(), EntityOperation.CREATE, "user");
            }

            var result = _controller.GetNotifications();

            var value = result.Value;
            Assert.NotNull(value);
            var countProp = value!.GetType().GetProperty("count");
            var count = (int)countProp!.GetValue(value)!;
            Assert.True(count <= 10, $"Expected max 10 notifications, got {count}");
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(1);

            Assert.NotNull(result);
            var value = result.Value;
            Assert.NotNull(value);

            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }

        [Fact]
        public void MarkAsRead_WithAnyId_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(999);

            Assert.NotNull(result);
            var value = result.Value;
            Assert.NotNull(value);

            var successProp = value.GetType().GetProperty("success");
            Assert.True((bool)successProp!.GetValue(value)!);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }
    }
}

