        [Fact]
        public void Constructor_ExactDivision_CorrectTotalPages()
        {
            // 20 items / 10 per page = 2 pages exactly
            var items = new List<int> { 1 };
            var result = new PaginatedList<int>(items, 20, 1, 10);

            Assert.Equal(2, result.TotalPages);
        }

        [Fact]
        public void HasPreviousPage_PageOne_ReturnsFalse_NotTrueForBoundary()
        {
            // This test kills the mutation > → >= on HasPreviousPage
            // PageIndex == 1 should be false; if mutated to >=, it would be true
            var result = new PaginatedList<int>(new List<int> { 1 }, 20, 1, 10);
            Assert.False(result.HasPreviousPage);
            Assert.Equal(1, result.PageIndex);
        }

        [Fact]
        public void HasNextPage_LastPage_ReturnsFalse_BoundaryExact()
        {
            // This test kills the mutation < → <= on HasNextPage
            // PageIndex == TotalPages should be false; if mutated to <=, it would be true
            var result = new PaginatedList<int>(new List<int> { 1 }, 20, 2, 10);
            Assert.Equal(2, result.TotalPages);
            Assert.Equal(2, result.PageIndex);
            Assert.False(result.HasNextPage);
        }

        [Fact]
        public void HasNextPage_PageBeforeLast_ReturnsTrue_BoundaryExact()
        {
            // PageIndex < TotalPages → true
            var result = new PaginatedList<int>(new List<int> { 1 }, 30, 2, 10);
            Assert.Equal(3, result.TotalPages);
            Assert.Equal(2, result.PageIndex);
            Assert.True(result.HasNextPage);
        }

        [Fact]
        public void Create_NonExactDivision_CorrectTotalPages()
        {
            // 21 items / 10 per page = ceil(2.1) = 3 pages
            // This kills mutation that removes (double) cast
            var source = Enumerable.Range(1, 21).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(3, result.TotalPages);
            Assert.Equal(10, result.Count);
        }

        [Fact]
        public void Create_FractionalPage_CeilingApplied()
        {
            // 11 items / 10 per page = ceil(1.1) = 2
            var source = Enumerable.Range(1, 11).AsQueryable();
            var result = PaginatedList<int>.Create(source, 1, 10);

            Assert.Equal(2, result.TotalPages);
            Assert.True(result.HasNextPage);
        }
    }
}

