[Fact]
public void DeleteConfirmed_CourseWithImagePath_AttemptsFileDelete()
{
    // Set up a course with a teaching material image path
    var course = _context.Courses.Find(1002)!;
    course.TeachingMaterialImagePath = "/Uploads/TeachingMaterials/test.jpg";
    _context.SaveChanges();

    // Should not throw even though file doesn't exist
    var result = _controller.DeleteConfirmed(1002);
    Assert.IsType<RedirectToActionResult>(result);
}

[Fact]
public void Create_POST_FileJustUnder5MB_AcceptsFile()
{
    // Test boundary: file just under 5MB should be accepted
    var course = new Course { CourseID = 6001, Title = "Boundary Test", Credits = 3, DepartmentID = 1 };
    var mockFile = CreateMockFile("photo.jpg", (5 * 1024 * 1024) - 1); // 5MB - 1 byte

    var result = _controller.Create(course, mockFile);

    var redirect = Assert.IsType<RedirectToActionResult>(result);
    Assert.Equal("Index", redirect.ActionName);
    Assert.False(_controller.ModelState.ContainsKey("teachingMaterialImage"));
}

[Fact]
public void Create_POST_FileExactly5MB_AcceptsFile()
{
    // 5MB exactly should be accepted (> 5MB is the reject condition)
    var course = new Course { CourseID = 6002, Title = "Exact 5MB", Credits = 3, DepartmentID = 1 };
    var mockFile = CreateMockFile("photo.png", 5 * 1024 * 1024);

    var result = _controller.Create(course, mockFile);

    var redirect = Assert.IsType<RedirectToActionResult>(result);
    Assert.Equal("Index", redirect.ActionName);
}

[Fact]
public void Create_POST_FileExactly5MBPlus1_RejectsFile()
{
    // 5MB + 1 byte should be rejected
    var course = new Course { CourseID = 6003, Title = "Over 5MB", Credits = 3, DepartmentID = 1 };
    var mockFile = CreateMockFile("photo.png", (5 * 1024 * 1024) + 1);

    var result = _controller.Create(course, mockFile) as ViewResult;

    Assert.NotNull(result);
    Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
    var errors = _controller.ModelState["teachingMaterialImage"]!.Errors;
    Assert.Contains(errors, e => e.ErrorMessage.Contains("5MB"));
}

