        [Fact]
        public void Index_DefaultPageSize_LimitsTo10Items()
        {
            // Add enough students to exceed page size
            for (int i = 100; i < 115; i++)
            {
                _context.Students.Add(new Student
                {
                    ID = i,
                    LastName = $"Student{i}",
                    FirstMidName = "Test",
                    EnrollmentDate = new DateTime(2023, 1, 1)
                });
            }
            _context.SaveChanges();

            // Now we have 3 seed + 15 new = 18 students, page size should be 10
            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(10, model.Count);
            Assert.True(model.HasNextPage);
        }

        [Fact]
        public void Index_SecondPage_ReturnsRemainingStudents()
        {
            // Add enough students to have 2 pages
            for (int i = 100; i < 115; i++)
            {
                _context.Students.Add(new Student
                {
                    ID = i,
                    LastName = $"Student{i:D3}",
                    FirstMidName = "Test",
                    EnrollmentDate = new DateTime(2023, 1, 1)
                });
            }
            _context.SaveChanges();

            var result = _controller.Index(null, null, null, 2) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.PageIndex);
            Assert.True(model.Count > 0);
            Assert.True(model.Count <= 10);
            Assert.True(model.HasPreviousPage);
        }

        #endregion
    }
}

