[Fact]
public void SendNotification_QueueCapEnforcement_TrimsOldestWhenOverMax()
{
    // Send exactly 500 items - should all stay
    for (int i = 0; i < 500; i++)
    {
        _sut.SendNotification("Type", i.ToString(), EntityOperation.CREATE, "user");
    }

    // At 500, no trimming should happen yet
    int countAt500 = 0;
    var tempService = new NotificationService();
    // Don't drain - just add one more to trigger cap
    _sut.SendNotification("Type", "500", EntityOperation.CREATE, "user");

    // After 501st item, queue should trim back to 500 or less
    int count = 0;
    while (_sut.ReceiveNotification() != null)
    {
        count++;
    }
    Assert.True(count <= 500, $"Expected queue size <= 500 after cap enforcement, got {count}");
    Assert.True(count >= 499, $"Expected queue size >= 499 (some items may have been trimmed), got {count}");
}

